// ---------- V5.0 AIRCRAFT OPERATIONS WORKSPACE ----------
// Configuration revisions, structured inspections, reference/spec library,
// consumables, cost accounting, trends, flight-test cards, timeline and reports.

if(!NAV.some(x=>x[0]==='ops')){
  const i=NAV.findIndex(x=>x[0]==='readiness');
  NAV.splice(i<0?NAV.length:i+1,0,['ops','Aircraft Ops']);
}

RECORD_ARRAYS.configuration='configurations';
RECORD_ARRAYS.spec='specs';
RECORD_ARRAYS.inspection='inspections';
RECORD_ARRAYS.flightcard='flightCards';
['configuration','spec','inspection','flightcard'].forEach(t=>SYNC_RECORD_TYPES.add(t));
SEED.configurations=SEED.configurations||[];
SEED.specs=SEED.specs||[];
SEED.inspections=SEED.inspections||[];
SEED.flightCards=SEED.flightCards||[];

const blankCloudDBOpsWorkspaceBase=blankCloudDB;
blankCloudDB=function(){
  const out=blankCloudDBOpsWorkspaceBase();
  out.configurations=[];out.specs=[];out.inspections=[];out.flightCards=[];
  return out;
};

const normalizeDBOpsWorkspaceBase=normalizeDB;
normalizeDB=function(){
  normalizeDBOpsWorkspaceBase();
  db.configurations=arr(db.configurations);
  db.specs=arr(db.specs);
  db.inspections=arr(db.inspections);
  db.flightCards=arr(db.flightCards);
  db.configurations.forEach(c=>{
    c.id=String(c.id||crypto.randomUUID());c.name=c.name||'Aircraft configuration';c.status=c.status||'Historical';c.effectiveDate=c.effectiveDate||'';
    c.equipmentIds=arr(c.equipmentIds).map(Number).filter(Number.isFinite);c.fuelCapacityGal=c.fuelCapacityGal??'';c.fuelConfig=c.fuelConfig||'';c.tires=c.tires||'';c.coolant=c.coolant||'';c.oil=c.oil||'';c.avionics=c.avionics||'';c.notes=c.notes||'';c.createdAt=c.createdAt||'';
  });
  db.specs.forEach(s=>{
    s.id=String(s.id||crypto.randomUUID());s.title=s.title||'Reference value';s.system=s.system||'General';s.value=s.value||'';s.units=s.units||'';s.status=s.status||'Needs Verification';s.source=s.source||'';s.sourceRevision=s.sourceRevision||'';s.sourceUrl=s.sourceUrl||'';s.documentId=s.documentId||null;s.equipmentId=s.equipmentId||null;s.notes=s.notes||'';
  });
  db.inspections.forEach(i=>{
    i.id=String(i.id||crypto.randomUUID());i.title=i.title||'Inspection';i.type=i.type||'General Inspection';i.date=i.date||today();i.status=i.status||'Open';i.projectId=i.projectId||null;i.airframeHours=i.airframeHours??'';i.engineHours=i.engineHours??'';i.notes=i.notes||'';
    i.items=arr(i.items).map(x=>({id:String(x.id||crypto.randomUUID()),section:x.section||'General',label:x.label||'Inspection item',result:x.result||'Pending',notes:x.notes||'',source:x.source||''}));
  });
  db.flightCards.forEach(f=>{
    f.id=String(f.id||crypto.randomUUID());f.title=f.title||'Flight test card';f.date=f.date||today();f.status=f.status||'Planned';f.projectId=f.projectId||null;f.runId=f.runId||null;f.conditions=f.conditions||'';f.notes=f.notes||'';
    f.items=arr(f.items).map(x=>({id:String(x.id||crypto.randomUUID()),objective:x.objective||'Test point',target:x.target||'',actual:x.actual||'',result:x.result||'Pending',notes:x.notes||''}));
  });
  db.parts=arr(db.parts);db.parts.forEach(p=>{p.partType=p.partType||((p.status==='Installed')?'Installed Component':'Inventory')});
  db.docs=arr(db.docs);db.docs.forEach(d=>{d.docStatus=d.docStatus||'Current';d.applicability=d.applicability||'';d.linkedEquipmentIds=arr(d.linkedEquipmentIds).map(Number).filter(Number.isFinite)});
  db.maintenance=arr(db.maintenance);db.maintenance.forEach(m=>{m.equipmentId=m.equipmentId||null;m.sourceDocId=m.sourceDocId||null;m.sourceNote=m.sourceNote||''});
};
normalizeDB();

let opsTab=sessionStorage.getItem('n594zs_ops_tab')||'configuration';
const OPS_TABS=[
  ['configuration','Configuration'],['inspections','Inspections'],['specs','Specs / Setup'],['consumables','Consumables'],['costs','Costs'],['trends','Test Trends'],['flightcards','Flight Cards'],['timeline','Timeline'],['reports','Reports']
];
function setOpsTab(tab){opsTab=tab;sessionStorage.setItem('n594zs_ops_tab',tab);renderOps()}
function renderOps(){
  const page=document.getElementById('page-ops');if(!page)return;
  page.innerHTML=`<div class="card ops-shell"><div class="toolbar"><div><h1>Aircraft Ops</h1><div class="muted">Configuration, inspections, references, consumables, test data and change history for N594ZS.</div></div><div class="mini-badge">v5 workflow</div></div><div class="ops-tabs">${OPS_TABS.map(([k,l])=>`<button class="${opsTab===k?'active':''}" onclick="setOpsTab('${k}')">${esc(l)}</button>`).join('')}</div><div id="opsContent"></div></div>`;
  const fn={configuration:renderOpsConfiguration,inspections:renderOpsInspections,specs:renderOpsSpecs,consumables:renderOpsConsumables,costs:renderOpsCosts,trends:renderOpsTrends,flightcards:renderOpsFlightCards,timeline:renderOpsTimeline,reports:renderOpsReports}[opsTab]||renderOpsConfiguration;
  fn();
}

// ---------- CONFIGURATION BASELINE / REVISIONS ----------
function activeConfiguration(){return db.configurations.find(c=>c.status==='Active')||db.configurations[0]||null}
function configurationEquipment(c){return arr(c?.equipmentIds).map(equipmentById).filter(Boolean)}
function installedEquipment(){return arr(db.equipment).filter(e=>e.status==='Installed')}
function configDisplayAvionics(c){return c?.avionics||installedEquipment().filter(e=>e.system==='Avionics / Instruments').map(e=>e.name).join(', ')||'Not recorded'}
function renderOpsConfiguration(){
  const box=document.getElementById('opsContent');if(!box)return;const active=activeConfiguration(),history=[...db.configurations].sort((a,b)=>(b.effectiveDate||'').localeCompare(a.effectiveDate||''));
  if(!active){box.innerHTML=`<div class="ops-empty"><h2>No configuration baseline yet</h2><p>Create an aircraft-specific snapshot of the engine, prop, fuel system, installed equipment and service fluids.</p><button class="primary" onclick="openConfigurationModal()">Create Current Configuration</button></div>`;return;}
  const eq=configurationEquipment(active);
  box.innerHTML=`<div class="ops-grid"><div class="ops-main"><div class="ops-panel"><div class="section-tools"><div><h2>${esc(active.name)}</h2><div class="muted">${esc(active.effectiveDate||'Effective date not set')} • ${pill(active.status)}</div></div><div class="action-row"><button class="secondary" onclick="createConfigurationRevision()">Create Revision</button><button class="primary" onclick="openConfigurationModal('${esc(active.id)}')">Edit Baseline</button></div></div><div class="config-grid">${configKV('Engine',eq.find(e=>e.system==='Engine')?.name||db.aircraft.engine||'Not recorded')}${configKV('Propeller',eq.find(e=>e.system==='Propeller')?.name||'Not recorded')}${configKV('Battery',eq.find(e=>e.category==='Battery')?.name||'Not recorded')}${configKV('Fuel capacity',active.fuelCapacityGal!==''?`${active.fuelCapacityGal} gal`:'Not recorded')}${configKV('Fuel configuration',active.fuelConfig||'Not recorded')}${configKV('Tires / gear',active.tires||'Not recorded')}${configKV('Coolant',active.coolant||'Not recorded')}${configKV('Oil',active.oil||'Not recorded')}</div><div class="detail-section"><label>Avionics / installed equipment summary</label><div class="detail-text">${esc(configDisplayAvionics(active))}</div></div><div class="detail-section"><label>Configuration notes</label><div class="detail-text">${esc(active.notes||'No notes.')}</div></div></div><div class="ops-panel"><div class="section-tools"><h3>Equipment in this configuration</h3><span class="mini-badge">${eq.length}</span></div>${eq.length?`<div class="related-grid">${eq.map(e=>`<button class="related-link" onclick="openEquipmentDetail(${e.id})"><b>${esc(e.name)}</b><small>${esc(e.system)} • ${esc(equipmentDisplayModel(e))}</small></button>`).join('')}</div>`:'<div class="empty">No equipment explicitly captured in this revision.</div>'}</div></div><div class="ops-side"><div class="ops-panel"><h3>Configuration history</h3>${history.map(c=>`<div class="config-history ${c.id===active.id?'active':''}"><div><b>${esc(c.name)}</b><small>${esc(c.effectiveDate||'No date')} • ${esc(c.status)}</small></div><button class="icon-btn" onclick="openConfigurationModal('${esc(c.id)}')">Edit</button></div>`).join('')}</div><div class="notice"><b>Configuration baseline</b><br>This is an as-recorded snapshot for project/maintenance organization. It does not itself establish airworthiness or replace required aircraft records.</div></div></div>`;
}
function configKV(label,value){return `<div class="config-kv"><span>${esc(label)}</span><b>${esc(String(value))}</b></div>`}
function openConfigurationModal(id=null,prefill=null){
  const c=id?db.configurations.find(x=>String(x.id)===String(id)):(prefill||{id:null,name:'Current N594ZS configuration',status:'Active',effectiveDate:today(),equipmentIds:installedEquipment().map(e=>e.id),fuelCapacityGal:db.aircraft.wb?.fuelMaxGallons||'',fuelConfig:'',tires:'',coolant:'',oil:'',avionics:'',notes:''});if(!c)return;
  const selected=new Set(arr(c.equipmentIds).map(Number));
  openModal(`${modalHeader(id?'Edit Configuration':'New Configuration Revision',c.name||'N594ZS configuration')}<div class="form-grid">${field('Configuration name','cfgName',c.name)}${field('Effective / snapshot date','cfgDate',c.effectiveDate,'date')}<div><label>Status</label><select id="cfgStatus">${['Active','Historical','Planned'].map(x=>`<option ${c.status===x?'selected':''}>${x}</option>`).join('')}</select></div>${field('Usable / configured fuel capacity (gal)','cfgFuelCap',c.fuelCapacityGal,'number','step="0.1" min="0"')}${textareaField('Fuel-system configuration','cfgFuel',c.fuelConfig)}${field('Tires / landing-gear configuration','cfgTires',c.tires)}${field('Coolant / mixture','cfgCoolant',c.coolant)}${field('Oil / service fluid','cfgOil',c.oil)}${textareaField('Avionics / configuration summary','cfgAvionics',c.avionics)}<div class="full"><label>Installed equipment included in this revision</label><div class="chip-select ops-chip-list">${arr(db.equipment).map(e=>`<label class="chip"><input class="cfg-equipment" type="checkbox" value="${e.id}" ${selected.has(Number(e.id))?'checked':''}> ${esc(e.name)}</label>`).join('')}</div></div>${textareaField('Notes','cfgNotes',c.notes)}</div><div class="modal-actions"><button class="secondary" onclick="closeModal()">Cancel</button><button class="primary" onclick="saveConfiguration('${esc(c.id||'')}')">Save Configuration</button></div>`,true);
}
function saveConfiguration(id){
  const old=id?db.configurations.find(x=>String(x.id)===String(id)):null,status=val('cfgStatus')||'Historical';
  const obj={...(old||{}),id:old?.id||crypto.randomUUID(),name:val('cfgName').trim()||'N594ZS configuration',status,effectiveDate:val('cfgDate'),equipmentIds:[...document.querySelectorAll('.cfg-equipment:checked')].map(x=>Number(x.value)).filter(Number.isFinite),fuelCapacityGal:val('cfgFuelCap'),fuelConfig:val('cfgFuel'),tires:val('cfgTires'),coolant:val('cfgCoolant'),oil:val('cfgOil'),avionics:val('cfgAvionics'),notes:val('cfgNotes'),createdAt:old?.createdAt||new Date().toISOString()};
  if(status==='Active')db.configurations.forEach(c=>{if(String(c.id)!==String(obj.id)&&c.status==='Active')c.status='Historical'});
  if(old)Object.assign(old,obj);else db.configurations.push(obj);closeModal();saveDB('Aircraft configuration saved.');setOpsTab('configuration');
}
function createConfigurationRevision(){const c=activeConfiguration();openConfigurationModal(null,{...(c?clone(c):{}),id:null,name:`N594ZS configuration ${today()}`,status:'Active',effectiveDate:today(),equipmentIds:installedEquipment().map(e=>e.id),createdAt:''})}

// ---------- INSPECTIONS ----------
function conditionInspectionTemplate(){return [
  ['Records / references','Applicable inspection checklist and current references identified'],['Airframe / fabric','Airframe / fabric inspection section completed'],['Flight controls','Flight-control inspection section completed'],['Landing gear / brakes','Landing gear / brake inspection section completed'],['Engine / propeller','Engine / propeller inspection section completed'],['Fuel / oil / cooling','Fuel / oil / cooling inspection section completed'],['Electrical / avionics','Electrical / avionics inspection section completed'],['Cabin / safety','Cabin / safety-equipment inspection section completed'],['Discrepancy review','Discrepancies recorded and disposition assigned'],['Closeout','Required records / signoffs completed outside this tracker']
].map(([section,label])=>({id:crypto.randomUUID(),section,label,result:'Pending',notes:'',source:''}))}
function renderOpsInspections(){
  const box=document.getElementById('opsContent');if(!box)return;const rows=[...db.inspections].sort((a,b)=>(b.date||'').localeCompare(a.date||''));
  box.innerHTML=`<div class="ops-panel"><div class="toolbar"><div><h2>Structured Inspections</h2><div class="muted">Pass / fail / N/A records with notes, references, findings and supporting photos/files.</div></div><div class="action-row"><button class="secondary" onclick="newConditionInspection()">+ Condition Inspection</button><button class="primary" onclick="openInspectionModal()">+ General Inspection</button></div></div><div class="notice">Use the applicable aircraft/engine/propeller/manufacturer inspection procedures and required records. This workspace organizes findings; it is not the inspection standard itself.</div><div class="table-wrap" style="margin-top:12px"><table><thead><tr><th>Date</th><th>Inspection</th><th>Type</th><th>Progress</th><th>Findings</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(i=>{const done=i.items.filter(x=>x.result!=='Pending').length,fails=i.items.filter(x=>x.result==='Fail').length;return `<tr class="click-row" onclick="openInspectionDetail('${esc(i.id)}')"><td>${esc(i.date||'—')}</td><td><b>${esc(i.title)}</b><div class="task-note">${esc(i.notes||'')}</div></td><td>${esc(i.type)}</td><td>${done}/${i.items.length}</td><td>${fails?`<span class="bad-text">${fails} fail</span>`:'—'}</td><td>${pill(i.status)}</td><td><button class="icon-btn" onclick="event.stopPropagation();openInspectionModal('${esc(i.id)}')">Edit</button></td></tr>`}).join('')||'<tr><td colspan="7" class="empty">No structured inspections yet.</td></tr>'}</tbody></table></div></div>`;
}
function newConditionInspection(){openInspectionModal(null,{title:`N594ZS Condition Inspection ${today()}`,type:'Condition Inspection',date:today(),status:'Open',projectId:null,airframeHours:db.aircraft.airframeHours||'',engineHours:db.aircraft.engineHours||'',notes:'',items:conditionInspectionTemplate()})}
function openInspectionModal(id=null,prefill=null){
  const i=id?db.inspections.find(x=>String(x.id)===String(id)):(prefill||{title:'',type:'General Inspection',date:today(),status:'Open',projectId:null,airframeHours:db.aircraft.airframeHours||'',engineHours:db.aircraft.engineHours||'',notes:'',items:[]});if(!i)return;
  openModal(`${modalHeader(id?'Edit Inspection':'New Inspection')}<div class="form-grid">${field('Inspection title','inspTitle',i.title)}<div><label>Type</label><select id="inspType">${['General Inspection','Condition Inspection','Fuel System Inspection','Electrical Inspection','Pre-Run Inspection','Post-Run Inspection','Other'].map(x=>`<option ${i.type===x?'selected':''}>${x}</option>`).join('')}</select></div>${field('Date','inspDate',i.date,'date')}<div><label>Status</label><select id="inspStatus">${['Open','In Progress','Completed','Completed w/ Findings'].map(x=>`<option ${i.status===x?'selected':''}>${x}</option>`).join('')}</select></div>${field('Airframe hours','inspAf',i.airframeHours,'number','step="0.1"')}${field('Engine hours','inspEng',i.engineHours,'number','step="0.1"')}<div class="full"><label>Linked project</label><select id="inspProject">${projectOptions(i.projectId)}</select></div>${textareaField('Notes / scope','inspNotes',i.notes)}</div><div class="modal-actions">${id?`<button class="danger" onclick="deleteInspection('${esc(i.id)}')">Move to Trash</button>`:''}<button class="secondary" onclick="closeModal()">Cancel</button><button class="primary" onclick="saveInspection('${esc(i.id||'')}')">Save</button></div>`,true);
}
function saveInspection(id){const old=id?db.inspections.find(x=>String(x.id)===String(id)):null,obj={...(old||{}),id:old?.id||crypto.randomUUID(),title:val('inspTitle').trim()||'Inspection',type:val('inspType')||'General Inspection',date:val('inspDate')||today(),status:val('inspStatus')||'Open',projectId:selectedNumber('inspProject'),airframeHours:val('inspAf'),engineHours:val('inspEng'),notes:val('inspNotes'),items:arr(old?.items)};if(old)Object.assign(old,obj);else db.inspections.push(obj);closeModal();saveDB('Inspection saved.');setOpsTab('inspections')}
function deleteInspection(id){if(!confirm('Move this inspection to Trash?'))return;db.inspections=db.inspections.filter(x=>String(x.id)!==String(id));closeModal();saveDB('Inspection moved to Trash.');setOpsTab('inspections')}
function inspectionCounts(i){return {pass:i.items.filter(x=>x.result==='Pass').length,fail:i.items.filter(x=>x.result==='Fail').length,na:i.items.filter(x=>x.result==='N/A').length,pending:i.items.filter(x=>x.result==='Pending').length}}
function openInspectionDetail(id){
  const i=db.inspections.find(x=>String(x.id)===String(id));if(!i)return;currentDetail={type:'inspection',id};const c=inspectionCounts(i),pr=i.projectId?projectById(Number(i.projectId)):null;
  openModal(`${modalHeader(i.title,`${i.type} • ${i.date}`)}<div class="summary-strip"><div class="summary-cell"><div class="lab">Status</div><div class="val">${pill(i.status)}</div></div><div class="summary-cell"><div class="lab">Pass</div><div class="val">${c.pass}</div></div><div class="summary-cell"><div class="lab">Findings</div><div class="val">${c.fail}</div></div><div class="summary-cell"><div class="lab">Pending</div><div class="val">${c.pending}</div></div></div><div class="detail-card"><div class="section-tools"><h3>Inspection Items</h3><button class="primary" onclick="editInspectionItem('${esc(i.id)}')">+ Add Item</button></div>${i.items.length?`<div class="table-wrap"><table class="inspection-table"><thead><tr><th>Section / item</th><th>Result</th><th>Reference</th><th>Notes</th><th></th></tr></thead><tbody>${i.items.map(item=>`<tr><td><b>${esc(item.section)}</b><div class="task-note">${esc(item.label)}</div></td><td><select onchange="setInspectionItemResult('${esc(i.id)}','${esc(item.id)}',this.value)">${['Pending','Pass','Fail','N/A'].map(r=>`<option ${item.result===r?'selected':''}>${r}</option>`).join('')}</select></td><td>${esc(item.source||'—')}</td><td>${esc(item.notes||'')}</td><td><div class="action-row"><button class="icon-btn" onclick="editInspectionItem('${esc(i.id)}','${esc(item.id)}')">Edit</button>${item.result==='Fail'?`<button class="icon-btn" onclick="createSquawkFromInspectionItem('${esc(i.id)}','${esc(item.id)}')">Squawk</button>`:''}</div></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No inspection items yet.</div>'}</div><div class="detail-grid"><div><div class="detail-card"><div class="section-tools"><h3>Photos / Files</h3><button class="icon-btn" onclick="chooseAttachments('inspection','${esc(i.id)}')">+ Upload</button></div><div class="attach-drop" onclick="chooseAttachments('inspection','${esc(i.id)}')" ondragover="event.preventDefault()" ondrop="handleEntityDrop(event,'inspection','${esc(i.id)}')">Drop inspection photos, reference pages or supporting files here</div><div id="attachments-inspection-${esc(i.id)}"></div></div></div><div><div class="detail-card"><h3>Context</h3>${pr?`<div class="kv click-row" onclick="openProjectDetail(${pr.id})"><span>Project</span><b>${esc(pr.title)}</b></div>`:'<div class="kv"><span>Project</span><b>Not linked</b></div>'}<div class="kv"><span>Airframe hours</span><b>${esc(i.airframeHours||'—')}</b></div><div class="kv"><span>Engine hours</span><b>${esc(i.engineHours||'—')}</b></div><div class="detail-section"><label>Notes</label><div class="detail-text">${esc(i.notes||'No notes.')}</div></div><div class="action-row"><button class="secondary" onclick="openInspectionModal('${esc(i.id)}')">Edit Inspection</button><button class="primary" onclick="completeInspection('${esc(i.id)}')">Complete</button></div></div></div></div>`,true);renderAttachments('inspection',i.id);
}
function editInspectionItem(inspectionId,itemId=null){const i=db.inspections.find(x=>String(x.id)===String(inspectionId));if(!i)return;const item=itemId?i.items.find(x=>String(x.id)===String(itemId)):{id:null,section:'General',label:'',result:'Pending',source:'',notes:''};openModal(`${modalHeader(itemId?'Edit Inspection Item':'Add Inspection Item',i.title)}<div class="form-grid">${field('Section','iiSection',item.section)}${field('Item / check','iiLabel',item.label)}<div><label>Result</label><select id="iiResult">${['Pending','Pass','Fail','N/A'].map(x=>`<option ${item.result===x?'selected':''}>${x}</option>`).join('')}</select></div>${field('Reference / source','iiSource',item.source)}${textareaField('Notes / finding','iiNotes',item.notes)}</div><div class="modal-actions">${itemId?`<button class="danger" onclick="deleteInspectionItem('${esc(inspectionId)}','${esc(itemId)}')">Delete Item</button>`:''}<button class="secondary" onclick="openInspectionDetail('${esc(inspectionId)}')">Cancel</button><button class="primary" onclick="saveInspectionItem('${esc(inspectionId)}','${esc(itemId||'')}')">Save Item</button></div>`,true)}
function saveInspectionItem(inspectionId,itemId){const i=db.inspections.find(x=>String(x.id)===String(inspectionId));if(!i)return;const obj={id:itemId||crypto.randomUUID(),section:val('iiSection')||'General',label:val('iiLabel').trim()||'Inspection item',result:val('iiResult')||'Pending',source:val('iiSource'),notes:val('iiNotes')};const n=i.items.findIndex(x=>String(x.id)===String(itemId));if(n>=0)i.items[n]=obj;else i.items.push(obj);saveDB('Inspection item saved.');openInspectionDetail(inspectionId)}
function deleteInspectionItem(inspectionId,itemId){const i=db.inspections.find(x=>String(x.id)===String(inspectionId));if(!i||!confirm('Delete this inspection item?'))return;i.items=i.items.filter(x=>String(x.id)!==String(itemId));saveDB('Inspection item deleted.');openInspectionDetail(inspectionId)}
function setInspectionItemResult(inspectionId,itemId,result){const i=db.inspections.find(x=>String(x.id)===String(inspectionId)),item=i?.items.find(x=>String(x.id)===String(itemId));if(!item)return;item.result=result;if(i.status==='Open')i.status='In Progress';saveDB('Inspection result updated.')}
function createSquawkFromInspectionItem(inspectionId,itemId){const i=db.inspections.find(x=>String(x.id)===String(inspectionId)),item=i?.items.find(x=>String(x.id)===String(itemId));if(!item)return;const sid=nextNumericId(db.squawks,800);db.squawks.push({id:sid,title:item.label,system:item.section||'General',severity:'Before Flight',status:'Open',discoveredDate:i.date||today(),airframeHours:i.airframeHours||'',engineHours:i.engineHours||'',description:item.notes||`Finding from ${i.title}.`,action:'',resolution:'',projectId:i.projectId||null,resolvedDate:'',sourceInspectionId:i.id});saveDB('Squawk created from inspection finding.');openSquawkDetail(sid)}
function completeInspection(id){const i=db.inspections.find(x=>String(x.id)===String(id));if(!i)return;const c=inspectionCounts(i);if(c.pending&& !confirm(`${c.pending} item(s) are still Pending. Complete this inspection record anyway?`))return;i.status=c.fail?'Completed w/ Findings':'Completed';saveDB('Inspection marked complete.');openInspectionDetail(id)}

// ---------- SPEC / SETUP LIBRARY ----------
function renderOpsSpecs(){
  const box=document.getElementById('opsContent');if(!box)return;const rows=[...db.specs].sort((a,b)=>a.system.localeCompare(b.system)||a.title.localeCompare(b.title));
  box.innerHTML=`<div class="ops-panel"><div class="toolbar"><div><h2>Specifications / Setup Library</h2><div class="muted">Save the exact value used, where it came from and which component/document it applies to.</div></div><button class="primary" onclick="openSpecModal()">+ Add Reference</button></div><div class="danger-note"><b>Reference library only.</b> Verify the current applicable manufacturer/aircraft/propeller documentation before using a stored value for maintenance or operation.</div><div class="table-wrap" style="margin-top:12px"><table><thead><tr><th>Reference</th><th>System</th><th>Value</th><th>Applies to</th><th>Source / rev</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(s=>{const e=s.equipmentId?equipmentById(Number(s.equipmentId)):null,d=s.documentId?docById(Number(s.documentId)):null;return `<tr class="click-row" onclick="openSpecDetail('${esc(s.id)}')"><td><b>${esc(s.title)}</b><div class="task-note">${esc(s.notes||'')}</div></td><td>${esc(s.system)}</td><td><b>${esc(s.value||'—')} ${esc(s.units||'')}</b></td><td>${esc(e?.name||'—')}</td><td>${esc(d?.name||s.source||'—')}${s.sourceRevision?` • ${esc(s.sourceRevision)}`:''}</td><td>${pill(s.status)}</td><td><button class="icon-btn" onclick="event.stopPropagation();openSpecModal('${esc(s.id)}')">Edit</button></td></tr>`}).join('')||'<tr><td colspan="7" class="empty">No stored setup/specification references yet.</td></tr>'}</tbody></table></div></div>`;
}
function openSpecModal(id=null){const s=id?db.specs.find(x=>String(x.id)===String(id)):{title:'',system:'General',value:'',units:'',status:'Needs Verification',source:'',sourceRevision:'',sourceUrl:'',documentId:null,equipmentId:null,notes:''};if(!s)return;openModal(`${modalHeader(id?'Edit Reference':'Add Reference')}<div class="form-grid">${field('Reference / setting','specTitle',s.title)}${field('System','specSystem',s.system)}${field('Value','specValue',s.value)}${field('Units','specUnits',s.units)}<div><label>Status</label><select id="specStatus">${['Needs Verification','Verified','Historical / Superseded'].map(x=>`<option ${s.status===x?'selected':''}>${x}</option>`).join('')}</select></div>${field('Source name','specSource',s.source)}${field('Source revision / section','specRevision',s.sourceRevision)}${field('Source URL','specUrl',s.sourceUrl)}<div><label>Applicable equipment</label><select id="specEquipment">${selectOptions(arr(db.equipment).map(e=>({value:e.id,label:e.name})),s.equipmentId,'— None —')}</select></div><div><label>Linked document</label><select id="specDocument">${selectOptions(arr(db.docs).map(d=>({value:d.id,label:d.name})),s.documentId,'— None —')}</select></div>${textareaField('Notes / context','specNotes',s.notes)}</div><div class="modal-actions">${id?`<button class="danger" onclick="deleteSpec('${esc(s.id)}')">Move to Trash</button>`:''}<button class="secondary" onclick="closeModal()">Cancel</button><button class="primary" onclick="saveSpec('${esc(s.id||'')}')">Save Reference</button></div>`,true)}
function saveSpec(id){const old=id?db.specs.find(x=>String(x.id)===String(id)):null,obj={...(old||{}),id:old?.id||crypto.randomUUID(),title:val('specTitle').trim()||'Reference value',system:val('specSystem')||'General',value:val('specValue'),units:val('specUnits'),status:val('specStatus')||'Needs Verification',source:val('specSource'),sourceRevision:val('specRevision'),sourceUrl:val('specUrl'),equipmentId:selectedNumber('specEquipment'),documentId:selectedNumber('specDocument'),notes:val('specNotes')};if(old)Object.assign(old,obj);else db.specs.push(obj);closeModal();saveDB('Reference saved.');setOpsTab('specs')}
function deleteSpec(id){if(!confirm('Move this reference to Trash?'))return;db.specs=db.specs.filter(x=>String(x.id)!==String(id));closeModal();saveDB('Reference moved to Trash.');setOpsTab('specs')}
function openSpecDetail(id){const s=db.specs.find(x=>String(x.id)===String(id));if(!s)return;currentDetail={type:'spec',id};const e=s.equipmentId?equipmentById(Number(s.equipmentId)):null,d=s.documentId?docById(Number(s.documentId)):null;openModal(`${modalHeader(s.title,`${s.system} • ${s.status}`)}<div class="summary-strip"><div class="summary-cell"><div class="lab">Stored value</div><div class="val">${esc(s.value||'—')} ${esc(s.units||'')}</div></div><div class="summary-cell"><div class="lab">Status</div><div class="val">${pill(s.status)}</div></div></div><div class="detail-grid"><div><div class="detail-card"><div class="section-tools"><h3>Source & context</h3><button class="icon-btn" onclick="openSpecModal('${esc(s.id)}')">Edit</button></div><div class="kv"><span>Source</span><b>${esc(s.source||'Not recorded')}</b></div><div class="kv"><span>Revision / section</span><b>${esc(s.sourceRevision||'—')}</b></div>${isURL(s.sourceUrl)?`<button class="secondary" onclick="window.open('${esc(s.sourceUrl)}','_blank','noopener')">Open Source</button>`:''}<div class="detail-section"><label>Notes</label><div class="detail-text">${esc(s.notes||'No notes.')}</div></div></div><div class="detail-card"><div class="section-tools"><h3>Files / screenshots</h3><button class="icon-btn" onclick="chooseAttachments('spec','${esc(s.id)}')">+ Upload</button></div><div id="attachments-spec-${esc(s.id)}"></div></div></div><div><div class="detail-card"><h3>Applies to</h3>${e?`<div class="kv click-row" onclick="openEquipmentDetail(${e.id})"><span>Equipment</span><b>${esc(e.name)}</b></div>`:'<div class="kv"><span>Equipment</span><b>Not linked</b></div>'}${d?`<div class="kv click-row" onclick="openDocumentDetail(${d.id})"><span>Document</span><b>${esc(d.name)}</b></div>`:'<div class="kv"><span>Document</span><b>Not linked</b></div>'}</div></div></div>`,true);renderAttachments('spec',s.id)}

// ---------- CONSUMABLES ----------
function renderOpsConsumables(){
  const box=document.getElementById('opsContent');if(!box)return;const rows=db.parts.filter(p=>p.partType==='Consumable'),low=rows.filter(p=>p.minQty!==''&&partAvailable(p)!==null&&partAvailable(p)<=num(p.minQty));
  box.innerHTML=`<div class="ops-panel"><div class="toolbar"><div><h2>Consumables Ledger</h2><div class="muted">Consumable materials and service stock, tied to Parts and Work Log consumption.</div></div><button class="primary" onclick="openPartModal()">+ Add Part / Material</button></div><div class="summary-strip"><div><span>Consumables</span><b>${rows.length}</b></div><div><span>Low / reorder</span><b>${low.length}</b></div><div><span>Consumed in work logs</span><b>${rows.reduce((s,p)=>s+partConsumedQty(p.id),0)}</b></div></div><div class="notice">Set <b>Part type = Consumable</b> when editing an item in Parts. Work Log consumption then becomes its usage history.</div><div class="table-wrap" style="margin-top:12px"><table><thead><tr><th>Material</th><th>System</th><th>Available</th><th>Used</th><th>Reorder level</th><th>Vendor</th><th></th></tr></thead><tbody>${rows.map(p=>`<tr class="click-row" onclick="openPartDetail(${p.id})"><td><b>${esc(p.name)}</b><div class="task-note">${esc(p.description||p.notes||'')}</div></td><td>${esc(p.system)}</td><td>${partAvailable(p)===null?'—':esc(partAvailable(p)+' '+(p.unit||''))}</td><td>${esc(partConsumedQty(p.id)+' '+(p.unit||''))}</td><td>${p.minQty===''?'—':esc(p.minQty+' '+(p.unit||''))}</td><td>${esc(p.vendor||'—')}</td><td><button class="icon-btn" onclick="event.stopPropagation();openLogModal(null,null,${p.id})">Log Use</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty">No Parts are classified as Consumable yet.</td></tr>'}</tbody></table></div></div>`;
}

// ---------- COST ACCOUNTING ----------
function canonicalSpendData(){
  const invoiceIds=new Set(arr(db.invoices).map(x=>String(x.invoice||x.id)).filter(Boolean));
  const invoiced=arr(db.invoices).reduce((s,x)=>s+num(x.total),0),shipping=arr(db.invoices).reduce((s,x)=>s+num(x.freight),0),tax=arr(db.invoices).reduce((s,x)=>s+num(x.tax),0),adjustments=arr(db.invoices).reduce((s,x)=>s+num(x.miscCharge)+(num(x.discount)||0),0);
  const unmatched=arr(db.purchases).filter(p=>!invoiceIds.has(String(p.invoice||''))&&purchasePriceKnown(p)).reduce((s,p)=>s+num(p.qty)*num(p.unitPrice),0);
  return {invoiced,unmatched,total:invoiced+unmatched,shipping,tax,adjustments};
}
function vendorSpendRows(){
  const map=new Map();
  for(const inv of arr(db.invoices)){const k=inv.vendor||'Unknown vendor';map.set(k,(map.get(k)||0)+num(inv.total))}
  const invoiceIds=new Set(arr(db.invoices).map(x=>String(x.invoice||x.id)).filter(Boolean));
  for(const p of arr(db.purchases))if(!invoiceIds.has(String(p.invoice||''))&&purchasePriceKnown(p)){const k=p.vendor||'Unknown vendor';map.set(k,(map.get(k)||0)+num(p.qty)*num(p.unitPrice))}
  return [...map.entries()].sort((a,b)=>b[1]-a[1]);
}
function systemLineSpendRows(){const map=new Map();for(const p of arr(db.purchases))if(purchasePriceKnown(p)){const k=p.system||'General';map.set(k,(map.get(k)||0)+num(p.qty)*num(p.unitPrice))}return [...map.entries()].sort((a,b)=>b[1]-a[1])}
function renderOpsCosts(){
  const box=document.getElementById('opsContent');if(!box)return;const c=canonicalSpendData(),equipmentCost=arr(db.equipment).reduce((s,e)=>s+(e.purchasePrice===''?0:num(e.purchasePrice)),0),returned=db.purchases.filter(p=>p.disposition==='Returned').length;
  box.innerHTML=`<div class="ops-grid"><div class="ops-main"><div class="ops-panel"><div class="toolbar"><div><h2>Cost Accounting</h2><div class="muted">Purchase spend is the canonical cash-spend view. Equipment and project-use totals are shown separately so the same item is not counted twice.</div></div></div><div class="cost-hero"><div><span>Canonical recorded purchase spend</span><b>${fmtMoney(c.total)}</b><small>Invoice totals + purchases without an invoice record</small></div><div><span>Actual invoice/order totals</span><b>${fmtMoney(c.invoiced)}</b><small>${db.invoices.length} invoice/order records</small></div><div><span>Unmatched purchase-line spend</span><b>${fmtMoney(c.unmatched)}</b><small>Not represented by an invoice total</small></div></div><div class="cost-breakdown"><div>${configKV('Shipping in invoice records',fmtMoney(c.shipping))}${configKV('Tax in invoice records',fmtMoney(c.tax))}${configKV('Adjustments / discounts recorded',fmtMoney(c.adjustments))}</div><div>${configKV('Installed-equipment acquisition values',fmtMoney(equipmentCost))}${configKV('Returned purchase lines',returned)}${configKV('Project material-use total',fmtMoney(db.projects.reduce((s,p)=>s+projectCost(p),0)))}</div></div><div class="notice"><b>Do not add the equipment or project-use figures to purchase spend.</b> They are alternate views of many of the same dollars. Returned/refunded purchases are not automatically netted unless the refund/credit is recorded.</div></div><div class="ops-panel"><h3>Spend by vendor</h3><div class="cost-list">${vendorSpendRows().map(([k,v])=>`<div><span>${esc(k)}</span><b>${fmtMoney(v)}</b></div>`).join('')||'<div class="empty">No vendor spend yet.</div>'}</div></div></div><div class="ops-side"><div class="ops-panel"><h3>Parts spend by system</h3><div class="tiny muted">Line-item merchandise only; shipping/tax stay in invoice totals.</div><div class="cost-list">${systemLineSpendRows().map(([k,v])=>`<div><span>${esc(k)}</span><b>${fmtMoney(v)}</b></div>`).join('')}</div></div></div></div>`;
}

// ---------- RUN / TEST TRENDS ----------
function numericRunSeries(key){return arr(db.runs).filter(r=>r.date&&r[key]!==''&&Number.isFinite(Number(r[key]))).sort((a,b)=>a.date.localeCompare(b.date)).map(r=>({date:r.date,value:Number(r[key]),id:r.id}))}
function sparklineSVG(series,label,unit=''){
  if(!series.length)return `<div class="trend-card"><b>${esc(label)}</b><div class="empty">No data yet.</div></div>`;
  const vals=series.map(x=>x.value),min=Math.min(...vals),max=Math.max(...vals),range=max-min||1,w=320,h=110,p=18;const pts=series.map((x,i)=>`${p+(i*(w-2*p)/Math.max(1,series.length-1))},${h-p-((x.value-min)/range)*(h-2*p)}`).join(' '),last=series[series.length-1];
  return `<div class="trend-card"><div class="section-tools"><b>${esc(label)}</b><span>${last.value}${esc(unit)}</span></div><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(label)} trend"><line x1="${p}" y1="${h-p}" x2="${w-p}" y2="${h-p}" class="trend-axis"/><polyline points="${pts}" class="trend-line"/></svg><div class="trend-meta"><span>${esc(series[0].date)} • ${min}${esc(unit)}</span><span>${esc(last.date)} • ${max}${esc(unit)}</span></div></div>`;
}
function renderOpsTrends(){const box=document.getElementById('opsContent');if(!box)return;box.innerHTML=`<div class="ops-panel"><div class="toolbar"><div><h2>Run / Test Trends</h2><div class="muted">Quick visual history of the indications you record in Runs / Tests.</div></div><button class="primary" onclick="openRunModal()">+ Log Run / Test</button></div><div class="trend-grid">${sparklineSVG(numericRunSeries('rpmMax'),'Maximum RPM',' rpm')}${sparklineSVG(numericRunSeries('oilPressureMin'),'Minimum Oil Pressure','')}${sparklineSVG(numericRunSeries('oilTempMax'),'Maximum Oil Temperature','')}${sparklineSVG(numericRunSeries('coolantTempMax'),'Maximum Coolant Temperature','')}${sparklineSVG(numericRunSeries('chtMax'),'Maximum CHT','')}${sparklineSVG(numericRunSeries('fuelPressureMin'),'Minimum Fuel Pressure','')}</div><div class="notice">Trend charts display the units exactly as you entered them in Runs / Tests. Keep units consistent between entries.</div></div>`}

// ---------- FLIGHT TEST CARDS ----------
function firstFlightCardItems(){return ['Aircraft configuration / loading recorded','Takeoff and climb observations','Engine indications and cooling behavior','Control feel / trim observations','Cruise indications and vibration observations','Approach / landing observations','Post-flight inspection / findings'].map(objective=>({id:crypto.randomUUID(),objective,target:'',actual:'',result:'Pending',notes:''}))}
function renderOpsFlightCards(){const box=document.getElementById('opsContent');if(!box)return;const rows=[...db.flightCards].sort((a,b)=>(b.date||'').localeCompare(a.date||''));box.innerHTML=`<div class="ops-panel"><div class="toolbar"><div><h2>Flight-Test Cards</h2><div class="muted">Structured data-collection cards. Enter your own targets and sources from applicable aircraft/engine/test planning references.</div></div><div class="action-row"><button class="secondary" onclick="newFirstFlightCard()">+ First-Flight Template</button><button class="primary" onclick="openFlightCardModal()">+ Blank Card</button></div></div><div class="danger-note">These cards are an organizational/data-recording aid, not a flight-test plan or authorization. Set limits, procedures and test points from the appropriate sources for your aircraft and operating limitations.</div><div class="table-wrap" style="margin-top:12px"><table><thead><tr><th>Date</th><th>Card</th><th>Status</th><th>Test points</th><th>Linked run</th><th></th></tr></thead><tbody>${rows.map(f=>`<tr class="click-row" onclick="openFlightCardDetail('${esc(f.id)}')"><td>${esc(f.date||'—')}</td><td><b>${esc(f.title)}</b><div class="task-note">${esc(f.conditions||f.notes||'')}</div></td><td>${pill(f.status)}</td><td>${f.items.filter(x=>x.result!=='Pending').length}/${f.items.length}</td><td>${f.runId?`<button class="linkbtn" onclick="event.stopPropagation();openRunDetail(${Number(f.runId)})">Run #${esc(f.runId)}</button>`:'—'}</td><td><button class="icon-btn" onclick="event.stopPropagation();openFlightCardModal('${esc(f.id)}')">Edit</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No flight-test cards yet.</td></tr>'}</tbody></table></div></div>`}
function newFirstFlightCard(){openFlightCardModal(null,{title:`N594ZS First-Flight Test Card ${today()}`,date:today(),status:'Planned',projectId:null,runId:null,conditions:'',notes:'',items:firstFlightCardItems()})}
function openFlightCardModal(id=null,prefill=null){const f=id?db.flightCards.find(x=>String(x.id)===String(id)):(prefill||{title:'',date:today(),status:'Planned',projectId:null,runId:null,conditions:'',notes:'',items:[]});if(!f)return;openModal(`${modalHeader(id?'Edit Flight-Test Card':'New Flight-Test Card')}<div class="form-grid">${field('Card title','fcTitle',f.title)}${field('Date','fcDate',f.date,'date')}<div><label>Status</label><select id="fcStatus">${['Planned','Ready','In Progress','Completed','Aborted'].map(x=>`<option ${f.status===x?'selected':''}>${x}</option>`).join('')}</select></div><div><label>Linked project</label><select id="fcProject">${projectOptions(f.projectId)}</select></div>${textareaField('Conditions / configuration','fcConditions',f.conditions)}${textareaField('Notes','fcNotes',f.notes)}</div><div class="modal-actions">${id?`<button class="danger" onclick="deleteFlightCard('${esc(f.id)}')">Move to Trash</button>`:''}<button class="secondary" onclick="closeModal()">Cancel</button><button class="primary" onclick="saveFlightCard('${esc(f.id||'')}')">Save Card</button></div>`,true)}
function saveFlightCard(id){const old=id?db.flightCards.find(x=>String(x.id)===String(id)):null,obj={...(old||{}),id:old?.id||crypto.randomUUID(),title:val('fcTitle').trim()||'Flight-test card',date:val('fcDate')||today(),status:val('fcStatus')||'Planned',projectId:selectedNumber('fcProject'),runId:old?.runId||null,conditions:val('fcConditions'),notes:val('fcNotes'),items:arr(old?.items)};if(old)Object.assign(old,obj);else db.flightCards.push(obj);closeModal();saveDB('Flight-test card saved.');setOpsTab('flightcards')}
function deleteFlightCard(id){if(!confirm('Move this flight-test card to Trash?'))return;db.flightCards=db.flightCards.filter(x=>String(x.id)!==String(id));closeModal();saveDB('Flight-test card moved to Trash.');setOpsTab('flightcards')}
function openFlightCardDetail(id){const f=db.flightCards.find(x=>String(x.id)===String(id));if(!f)return;currentDetail={type:'flightcard',id};const pr=f.projectId?projectById(Number(f.projectId)):null,run=f.runId?db.runs.find(r=>Number(r.id)===Number(f.runId)):null;openModal(`${modalHeader(f.title,`${f.date} • ${f.status}`)}<div class="detail-card"><div class="section-tools"><h3>Test Points</h3><button class="primary" onclick="editFlightCardItem('${esc(f.id)}')">+ Add Test Point</button></div>${f.items.length?`<div class="table-wrap"><table><thead><tr><th>Objective</th><th>Target / source</th><th>Actual</th><th>Result</th><th></th></tr></thead><tbody>${f.items.map(x=>`<tr><td><b>${esc(x.objective)}</b><div class="task-note">${esc(x.notes||'')}</div></td><td class="flight-target-source">${esc(x.target||'—')}</td><td>${esc(x.actual||'—')}</td><td>${pill(x.result)}</td><td><button class="icon-btn" onclick="editFlightCardItem('${esc(f.id)}','${esc(x.id)}')">Edit</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No test points yet.</div>'}</div><div class="detail-grid"><div><div class="detail-card"><h3>Conditions / notes</h3><div class="detail-text">${esc(f.conditions||'No conditions recorded.')}</div><div class="detail-section"><label>Notes</label><div class="detail-text">${esc(f.notes||'No notes.')}</div></div></div><div class="detail-card"><div class="section-tools"><h3>Photos / Files</h3><button class="icon-btn" onclick="chooseAttachments('flightcard','${esc(f.id)}')">+ Upload</button></div><div id="attachments-flightcard-${esc(f.id)}"></div></div></div><div><div class="detail-card"><h3>Links</h3>${pr?`<div class="kv click-row" onclick="openProjectDetail(${pr.id})"><span>Project</span><b>${esc(pr.title)}</b></div>`:'<div class="kv"><span>Project</span><b>Not linked</b></div>'}${run?`<div class="kv click-row" onclick="openRunDetail(${run.id})"><span>Run / test</span><b>${esc(run.date)} • ${esc(run.type)}</b></div>`:'<div class="kv"><span>Run / test</span><b>Not linked</b></div>'}<div class="action-row" style="margin-top:10px"><button class="secondary" onclick="openFlightCardModal('${esc(f.id)}')">Edit Card</button>${!run?`<button class="primary" onclick="createRunFromFlightCard('${esc(f.id)}')">Create Flight-Test Run</button>`:''}</div></div></div></div>`,true);renderAttachments('flightcard',f.id)}
function editFlightCardItem(cardId,itemId=null){const f=db.flightCards.find(x=>String(x.id)===String(cardId));if(!f)return;const x=itemId?f.items.find(i=>String(i.id)===String(itemId)):{id:null,objective:'',target:'',actual:'',result:'Pending',notes:''};openModal(`${modalHeader(itemId?'Edit Test Point':'Add Test Point',f.title)}<div class="form-grid">${textareaField('Objective / observation','fciObjective',x.objective)}${textareaField('Target / expected / source','fciTarget',x.target)}${textareaField('Actual result / measurement','fciActual',x.actual)}<div><label>Result</label><select id="fciResult">${['Pending','Satisfactory','Follow-up Needed','N/A'].map(r=>`<option ${x.result===r?'selected':''}>${r}</option>`).join('')}</select></div>${textareaField('Notes','fciNotes',x.notes)}</div><div class="modal-actions">${itemId?`<button class="danger" onclick="deleteFlightCardItem('${esc(cardId)}','${esc(itemId)}')">Delete</button>`:''}<button class="secondary" onclick="openFlightCardDetail('${esc(cardId)}')">Cancel</button><button class="primary" onclick="saveFlightCardItem('${esc(cardId)}','${esc(itemId||'')}')">Save Point</button></div>`,true)}
function saveFlightCardItem(cardId,itemId){const f=db.flightCards.find(x=>String(x.id)===String(cardId));if(!f)return;const obj={id:itemId||crypto.randomUUID(),objective:val('fciObjective').trim()||'Test point',target:val('fciTarget'),actual:val('fciActual'),result:val('fciResult')||'Pending',notes:val('fciNotes')};const n=f.items.findIndex(x=>String(x.id)===String(itemId));if(n>=0)f.items[n]=obj;else f.items.push(obj);saveDB('Flight-test point saved.');openFlightCardDetail(cardId)}
function deleteFlightCardItem(cardId,itemId){const f=db.flightCards.find(x=>String(x.id)===String(cardId));if(!f||!confirm('Delete this test point?'))return;f.items=f.items.filter(x=>String(x.id)!==String(itemId));saveDB('Test point deleted.');openFlightCardDetail(cardId)}
function createRunFromFlightCard(cardId){const f=db.flightCards.find(x=>String(x.id)===String(cardId));if(!f)return;const id=nextNumericId(db.runs,900);db.runs.push({id,date:f.date||today(),type:'Flight Test',durationMin:'',tachStart:db.aircraft.engineHours||'',tachEnd:'',rpmMax:'',oilPressureMin:'',oilTempMax:'',coolantTempMax:'',chtMax:'',fuelPressureMin:'',fuelPressureMax:'',outcome:'Follow-up Needed',observations:`Flight-test card: ${f.title}`,notes:f.notes||'',projectIds:f.projectId?[Number(f.projectId)]:[]});f.runId=id;f.status='In Progress';saveDB('Flight-test run created and linked.');openRunDetail(id)}

// ---------- TIMELINE / REPORTS ----------
function eventItem(date,kind,label,sub='',go=''){return date?{date,kind,label,sub,go}:null}
function collectAircraftTimeline(){
  const ev=[];
  for(const inv of arr(db.invoices)){const items=db.purchases.filter(p=>String(p.invoice)===String(inv.invoice));ev.push(eventItem(inv.invoiceDate,'Purchase',`${inv.vendor||'Vendor'} ${inv.invoice||inv.order||''}`,`${items.length} item${items.length===1?'':'s'} • ${fmtMoney(inv.total)}`,items.length?`openInvoiceGroup('${String(inv.invoice).replace(/'/g,"\\'")}')`:''))}
  const invoiceIds=new Set(arr(db.invoices).map(x=>String(x.invoice||x.id)).filter(Boolean));
  const groups=new Map();for(const p of arr(db.purchases))if(p.shipDate&&!invoiceIds.has(String(p.invoice||''))){const k=`${p.vendor}|${p.invoice||p.order||p.shipDate}`;if(!groups.has(k))groups.set(k,{date:p.shipDate,vendor:p.vendor||'Vendor',ref:p.invoice||p.order||'',items:[],total:0});const g=groups.get(k);g.items.push(p);if(purchasePriceKnown(p))g.total+=num(p.qty)*num(p.unitPrice)}
  for(const g of groups.values())ev.push(eventItem(g.date,'Purchase',`${g.vendor}${g.ref?' '+g.ref:''}`,`${g.items.length} item${g.items.length===1?'':'s'} • ${fmtMoney(g.total)}`,g.items[0]?`openPurchaseDetail('${String(g.items[0].id).replace(/'/g,"\\'")}')`:''));
  for(const e of arr(db.equipment)){if(e.purchaseDate)ev.push(eventItem(e.purchaseDate,'Equipment',`Purchased: ${e.name}`,e.vendor?`${e.vendor} • ${fmtMoney(e.purchasePrice)}`:fmtMoney(e.purchasePrice),`openEquipmentDetail(${e.id})`));if(e.installDate)ev.push(eventItem(e.installDate,'Equipment',`Installed: ${e.name}`,e.location||'',`openEquipmentDetail(${e.id})`));for(const h of arr(e.history))if(h.date)ev.push(eventItem(h.date,'Equipment',`${e.name}: ${h.action}`,h.notes||'',`openEquipmentDetail(${e.id})`))}
  for(const l of arr(db.logs))ev.push(eventItem(l.date,'Work',l.work,l.system||'',`openLogDetail(${l.id})`));
  for(const r of arr(db.runs))ev.push(eventItem(r.date,'Run / Test',r.type,r.outcome||'',`openRunDetail(${r.id})`));
  for(const s of arr(db.squawks)){ev.push(eventItem(s.discoveredDate,'Squawk',`Opened: ${s.title}`,`${s.severity} • ${s.status}`,`openSquawkDetail(${s.id})`));if(s.resolvedDate)ev.push(eventItem(s.resolvedDate,'Squawk',`Resolved: ${s.title}`,s.resolution||'',`openSquawkDetail(${s.id})`))}
  for(const p of arr(db.projects))for(const u of arr(p.updates))ev.push(eventItem(u.date,'Project',p.title,u.text||'',`openProjectDetail(${p.id})`));
  for(const c of arr(db.configurations))ev.push(eventItem(c.effectiveDate,'Configuration',c.name,c.status,`setOpsTab('configuration')`));
  for(const i of arr(db.inspections))ev.push(eventItem(i.date,'Inspection',i.title,`${i.status} • ${inspectionCounts(i).fail} finding(s)`,`openInspectionDetail('${String(i.id).replace(/'/g,"\\'")}')`));
  for(const f of arr(db.flightCards))ev.push(eventItem(f.date,'Flight Card',f.title,f.status,`openFlightCardDetail('${String(f.id).replace(/'/g,"\\'")}')`));
  return ev.filter(Boolean).sort((a,b)=>(b.date||'').localeCompare(a.date||''));
}
function renderTimelineList(events,limit=150){return `<div class="aircraft-timeline">${events.slice(0,limit).map(e=>`<div class="timeline-event ${e.go?'click-row':''}" ${e.go?`onclick="${e.go}"`:''}><div class="timeline-date-badge">${esc(e.date)}</div><div><span class="mini-badge">${esc(e.kind)}</span><b>${esc(e.label)}</b><small>${esc(e.sub||'')}</small></div></div>`).join('')||'<div class="empty">No timeline events in this range.</div>'}</div>`}
function renderOpsTimeline(){const box=document.getElementById('opsContent');if(!box)return;const events=collectAircraftTimeline();box.innerHTML=`<div class="ops-panel"><div class="toolbar"><div><h2>Aircraft Timeline</h2><div class="muted">Chronological view assembled from purchases, equipment, work, runs, squawks, projects, configuration revisions and inspections.</div></div><span class="mini-badge">${events.length} events</span></div>${renderTimelineList(events)}</div>`}
function daysAgoISO(days){const d=new Date();d.setDate(d.getDate()-days);return d.toISOString().slice(0,10)}
function renderOpsReports(){const box=document.getElementById('opsContent');if(!box)return;box.innerHTML=`<div class="ops-panel"><div class="toolbar"><div><h2>What Changed Since…</h2><div class="muted">Build a concise activity report from the records in this tracker.</div></div><button class="secondary" onclick="window.print()">Print</button></div><div class="report-controls"><label>Since <input id="reportSince" type="date" value="${daysAgoISO(30)}" onchange="renderChangeReport()"></label><button class="primary" onclick="renderChangeReport()">Generate Report</button></div><div id="changeReport"></div></div>`;renderChangeReport()}
function renderChangeReport(){const box=document.getElementById('changeReport');if(!box)return;const since=val('reportSince')||'0000-00-00',events=collectAircraftTimeline().filter(e=>e.date>=since),counts={};events.forEach(e=>counts[e.kind]=(counts[e.kind]||0)+1);const active=activeConfiguration(),openSq=openSquawks().length,openProjects=db.projects.filter(p=>p.status!=='Done').length;box.innerHTML=`<div class="report-summary"><div><span>Events</span><b>${events.length}</b></div><div><span>Open projects</span><b>${openProjects}</b></div><div><span>Open squawks</span><b>${openSq}</b></div><div><span>Configuration</span><b>${esc(active?.name||'Not set')}</b></div></div><div class="report-counts">${Object.entries(counts).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<span class="mini-badge">${esc(k)} ${v}</span>`).join('')}</div>${renderTimelineList(events,250)}`}

