const openPartModalOpsBase=openPartModal;
openPartModal=function(id=null,projectId=null){
  openPartModalOpsBase(id,projectId);const p=id?partById(id):null,box=document.getElementById('modalBox'),system=document.getElementById('ptSystem');if(!box||!system||document.getElementById('ptType'))return;const host=system.closest('div');host?.insertAdjacentHTML('afterend',`<div><label>Part type</label><select id="ptType">${['Inventory','Consumable','Spare','Installed Component','Supply'].map(x=>`<option ${(p?.partType||'Inventory')===x?'selected':''}>${x}</option>`).join('')}</select></div>`);
};
savePart=function(id,projectId=null){
  const old=id?partById(id):null,o={name:val('ptName'),description:val('ptDescription'),partNo:val('ptPN'),system:val('ptSystem')||'General',partType:val('ptType')||old?.partType||'Inventory',unit:val('ptUnit')||'ea',stockQty:val('ptStock')===''?'':num(val('ptStock')),minQty:val('ptMin')===''?'':num(val('ptMin')),status:val('ptStatus'),vendor:val('ptVendor'),url:val('ptUrl'),unitCost:val('ptCost'),location:val('ptLocation'),purchaseDate:val('ptPurchase'),notes:val('ptNotes')};if(!o.name)return alert('Part name is required.');let pid=id;if(old)Object.assign(old,o);else{pid=uid();db.parts.push({id:pid,...o,linkedProjectIds:projectId?[projectId]:[],updates:[]})}saveDB(id?'Part updated.':'Part added.');closeModal();
};

