const openDocModalOpsBase=openDocModal;
openDocModal=function(id=null,projectId=null){
  openDocModalOpsBase(id,projectId);const d=id?docById(id):null,box=document.getElementById('modalBox'),notes=document.getElementById('dcNotes');if(!box||!notes||document.getElementById('dcStatus'))return;const selected=new Set(arr(d?.linkedEquipmentIds).map(Number));const host=notes.closest('.full')||notes.parentElement;host?.insertAdjacentHTML('beforebegin',`<div><label>Document status</label><select id="dcStatus">${['Current','Reference','Superseded'].map(x=>`<option ${(d?.docStatus||'Current')===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="full"><label>Applicability</label><input id="dcApplicability" value="${esc(d?.applicability||'')}" placeholder="e.g. N594ZS current 912 configuration / Rotax 912 ULS"></div><div class="full"><label>Applicable equipment</label><div class="chip-select ops-chip-list">${arr(db.equipment).map(e=>`<label class="chip"><input class="doc-equipment" type="checkbox" value="${e.id}" ${selected.has(Number(e.id))?'checked':''}> ${esc(e.name)}</label>`).join('')}</div></div>`);
};
saveDoc=function(id,projectId=null){
  const old=id?docById(id):null,o={name:val('dcName'),type:val('dcType'),revision:val('dcRevision'),issueDate:val('dcIssue'),system:val('dcSystem'),publisher:val('dcPublisher'),location:val('dcLocation'),docStatus:val('dcStatus')||old?.docStatus||'Current',applicability:val('dcApplicability'),linkedEquipmentIds:[...document.querySelectorAll('.doc-equipment:checked')].map(x=>Number(x.value)).filter(Number.isFinite),notes:val('dcNotes')};if(!o.name)return alert('Document name is required.');if(old)Object.assign(old,o);else db.docs.push({id:uid(),...o,linkedProjectIds:projectId?[projectId]:[],linkedPartIds:[],linkedLogIds:[],updates:[]});closeModal();saveDB(id?'Document updated.':'Document added.');
};
renderDocuments=function(){const statuses=unique(db.docs.map(d=>d.docStatus).filter(Boolean));document.getElementById('page-documents').innerHTML=`<div class="card"><div class="toolbar"><div><h1>Documents</h1><div class="muted">Manuals, diagrams and records with revision, status and applicability to N594ZS equipment/configuration.</div></div><button class="btn primary" onclick="openDocModal()">+ Add Document</button></div><div class="controls"><input id="docSearch" placeholder="Search documents…" oninput="renderDocRows()"><select id="docType" onchange="renderDocRows()"><option value="">All types</option>${unique(db.docs.map(d=>d.type).filter(Boolean)).sort().map(s=>`<option>${esc(s)}</option>`).join('')}</select><select id="docStatusFilter" onchange="renderDocRows()"><option value="">All statuses</option>${statuses.map(s=>`<option>${esc(s)}</option>`).join('')}</select></div><div class="table-wrap" style="margin-top:11px"><table><thead><tr><th>Document</th><th>Type</th><th>Revision</th><th>Status</th><th>Applies to</th><th>System</th><th>Location</th><th></th></tr></thead><tbody id="docRows"></tbody></table></div></div>`;renderDocRows()};
renderDocRows=function(){const el=document.getElementById('docRows');if(!el)return;const q=(val('docSearch')||'').toLowerCase(),type=val('docType'),status=val('docStatusFilter');const rows=db.docs.filter(d=>(!q||[d.name,d.type,d.revision,d.system,d.publisher,d.location,d.notes,d.applicability,...d.linkedEquipmentIds.map(id=>equipmentById(id)?.name||'')].join(' ').toLowerCase().includes(q))&&(!type||d.type===type)&&(!status||d.docStatus===status));el.innerHTML=rows.map(d=>`<tr class="click-row" onclick="openDocumentDetail(${d.id})"><td><b>${esc(d.name)}</b><div class="task-note">${esc(d.publisher||d.notes||'')}</div></td><td>${esc(d.type||'—')}</td><td>${esc(d.revision||'—')}</td><td>${pill(d.docStatus)}</td><td>${esc(d.applicability||d.linkedEquipmentIds.map(id=>equipmentById(id)?.name).filter(Boolean).join(', ')||'—')}</td><td>${esc(d.system||'—')}</td><td>${isURL(d.location)?'<span class="blue pill">Web link</span>':esc(d.location||'—')}</td><td><button class="icon-btn" onclick="event.stopPropagation();openDocModal(${d.id})">Edit</button></td></tr>`).join('')||'<tr><td colspan="8" class="empty">No matching documents.</td></tr>'};
const openDocumentDetailOpsBase=openDocumentDetail;
openDocumentDetail=function(id){openDocumentDetailOpsBase(id);const d=docById(id),box=document.getElementById('modalBox');if(!d||!box||box.querySelector('[data-doc-applicability]'))return;const card=document.createElement('div');card.className='detail-card';card.dataset.docApplicability='1';card.innerHTML=`<h3>Applicability</h3><div class="kv"><span>Status</span><b>${pill(d.docStatus||'Current')}</b></div><div class="detail-section"><label>Applies to</label><div class="detail-text">${esc(d.applicability||'Not specified.')}</div></div>${d.linkedEquipmentIds.length?d.linkedEquipmentIds.map(eid=>{const e=equipmentById(eid);return e?`<div class="kv click-row" onclick="openEquipmentDetail(${e.id})"><span>Equipment</span><b>${esc(e.name)}</b></div>`:''}).join(''):''}`;box.appendChild(card)};

