// ---------- SEARCH + RENDER WRAPPERS ----------
const renderSearchPageOpsBase=renderSearchPage;
renderSearchPage=async function(q=''){
  await renderSearchPageOpsBase(q);const term=(q||document.getElementById('globalSearchInput')?.value||'').trim().toLowerCase(),box=document.querySelector('#page-search .search-results');if(!term||!box)return;
  const add=(kind,label,sub,go)=>box.insertAdjacentHTML('beforeend',`<button class="search-result" onclick="${go}"><span class="mini-badge">${esc(kind)}</span><b>${esc(label)}</b><small>${esc(sub||'')}</small></button>`);
  db.configurations.filter(x=>cloudStableJSON(x).toLowerCase().includes(term)).slice(0,20).forEach(x=>add('Configuration',x.name,`${x.effectiveDate} • ${x.status}`,"navTo('ops');setOpsTab('configuration')"));
  db.specs.filter(x=>cloudStableJSON(x).toLowerCase().includes(term)).slice(0,20).forEach(x=>add('Spec',x.title,`${x.value} ${x.units} • ${x.system}`,`openSpecDetail('${String(x.id).replace(/'/g,"\\'")}')`));
  db.inspections.filter(x=>cloudStableJSON(x).toLowerCase().includes(term)).slice(0,20).forEach(x=>add('Inspection',x.title,`${x.date} • ${x.status}`,`openInspectionDetail('${String(x.id).replace(/'/g,"\\'")}')`));
  db.flightCards.filter(x=>cloudStableJSON(x).toLowerCase().includes(term)).slice(0,20).forEach(x=>add('Flight Card',x.title,`${x.date} • ${x.status}`,`openFlightCardDetail('${String(x.id).replace(/'/g,"\\'")}')`));
  const sub=document.querySelector('#page-search .toolbar .muted'),count=box.querySelectorAll('.search-result').length;if(sub)sub.textContent=`${count} result${count===1?'':'s'} for “${term}”`;if(count)box.querySelectorAll('.empty').forEach(x=>x.remove());
};

